/* ==========================================================
   Homebrew Channel bubbles: pure CSS port of bubbles.c
   No markup needed. Uses html/body ::before and ::after.
   ========================================================== */

:root {
  /* Your three bubble PNGs, embedded so no file paths are needed. */
  --bubble-1: url("data:image/png;base64,");
  --bubble-2: url("data:image/png;base64,");
  --bubble-3: url("data:image/png;base64,");

  --bubble-opacity: 0.85;
  /* -1 = behind the UI like on the Wii. Use 9999 if the app's
     panels are opaque and hide them (they still won't block clicks). */
  --bubble-z: -1;
}

html::before,
html::after,
body::before,
body::after {
  content: "";
  position: fixed;
  inset: 0;                 /* one screen tall, full width */
  pointer-events: none;     /* never blocks clicks or text selection */
  z-index: var(--bubble-z);
  opacity: var(--bubble-opacity);
  background-repeat: no-repeat;
  will-change: transform, background-position;
}

/* The whole group rises one screen below to one screen above.
   Two groups per speed, half a cycle apart, keep the count even. */
@keyframes hbc-rise {
  from { transform: translateY(100vh); }
  to   { transform: translateY(-100vh); }
}

/* html::before: 10 bubbles, rises in 10s */
html::before {
  background-image:
    var(--bubble-2),
    var(--bubble-3),
    var(--bubble-1),
    var(--bubble-1),
    var(--bubble-3),
    var(--bubble-2),
    var(--bubble-2),
    var(--bubble-1),
    var(--bubble-1),
    var(--bubble-3);
  background-size: 24px, 40px, 32px, 58px, 30px, 46px, 37px, 59px, 37px, 35px;
  animation:
    hbc-rise 10s linear -2.5s infinite,
    hbc-sway-a 0.7s ease-in-out -2.5s infinite alternate;
}
@keyframes hbc-sway-a {
  from {
    background-position:
      calc(90.2vw - 3px) 4.2vh,
      calc(22.0vw + 3px) 11.7vh,
      calc(78.9vw + 3px) 22.0vh,
      calc(92.8vw - 3px) 31.4vh,
      calc(30.7vw - 8px) 47.5vh,
      calc(11.1vw + 3px) 56.7vh,
      calc(45.3vw - 3px) 68.4vh,
      calc(55.4vw - 3px) 75.2vh,
      calc(49.6vw - 3px) 82.3vh,
      calc(55.3vw + 7px) 98.0vh;
  }
  to {
    background-position:
      calc(90.2vw + 3px) 4.2vh,
      calc(22.0vw - 3px) 11.7vh,
      calc(78.9vw - 3px) 22.0vh,
      calc(92.8vw + 3px) 31.4vh,
      calc(30.7vw + 8px) 47.5vh,
      calc(11.1vw - 3px) 56.7vh,
      calc(45.3vw + 3px) 68.4vh,
      calc(55.4vw + 3px) 75.2vh,
      calc(49.6vw + 3px) 82.3vh,
      calc(55.3vw - 7px) 98.0vh;
  }
}

/* html::after: 10 bubbles, rises in 10s */
html::after {
  background-image:
    var(--bubble-3),
    var(--bubble-1),
    var(--bubble-3),
    var(--bubble-1),
    var(--bubble-1),
    var(--bubble-3),
    var(--bubble-1),
    var(--bubble-1),
    var(--bubble-2),
    var(--bubble-1);
  background-size: 26px, 46px, 37px, 33px, 34px, 59px, 43px, 46px, 59px, 30px;
  animation:
    hbc-rise 10s linear -7.5s infinite,
    hbc-sway-b 0.7s ease-in-out -7.5s infinite alternate;
}
@keyframes hbc-sway-b {
  from {
    background-position:
      calc(76.1vw - 5px) 1.6vh,
      calc(70.0vw + 3px) 13.5vh,
      calc(34.3vw - 6px) 28.5vh,
      calc(73.4vw + 3px) 32.0vh,
      calc(17.5vw + 3px) 44.2vh,
      calc(40.6vw - 3px) 53.9vh,
      calc(23.6vw - 3px) 62.9vh,
      calc(41.0vw - 3px) 74.0vh,
      calc(85.7vw + 5px) 87.2vh,
      calc(46.8vw - 3px) 94.2vh;
  }
  to {
    background-position:
      calc(76.1vw + 5px) 1.6vh,
      calc(70.0vw - 3px) 13.5vh,
      calc(34.3vw + 6px) 28.5vh,
      calc(73.4vw - 3px) 32.0vh,
      calc(17.5vw - 3px) 44.2vh,
      calc(40.6vw + 3px) 53.9vh,
      calc(23.6vw + 3px) 62.9vh,
      calc(41.0vw + 3px) 74.0vh,
      calc(85.7vw - 5px) 87.2vh,
      calc(46.8vw + 3px) 94.2vh;
  }
}

/* body::before: 10 bubbles, rises in 16s */
body::before {
  background-image:
    var(--bubble-2),
    var(--bubble-1),
    var(--bubble-2),
    var(--bubble-1),
    var(--bubble-3),
    var(--bubble-3),
    var(--bubble-2),
    var(--bubble-1),
    var(--bubble-1),
    var(--bubble-2);
  background-size: 46px, 29px, 64px, 53px, 44px, 26px, 55px, 32px, 30px, 42px;
  animation:
    hbc-rise 16s linear -4s infinite,
    hbc-sway-c 1.0s ease-in-out -4s infinite alternate;
}
@keyframes hbc-sway-c {
  from {
    background-position:
      calc(57.9vw - 3px) 1.8vh,
      calc(83.3vw + 3px) 15.9vh,
      calc(13.4vw + 5px) 27.8vh,
      calc(15.4vw - 3px) 37.0vh,
      calc(4.1vw - 3px) 48.6vh,
      calc(29.7vw - 6px) 56.1vh,
      calc(73.8vw - 6px) 65.3vh,
      calc(78.1vw - 3px) 76.9vh,
      calc(75.5vw + 3px) 84.8vh,
      calc(9.5vw - 5px) 91.8vh;
  }
  to {
    background-position:
      calc(57.9vw + 3px) 1.8vh,
      calc(83.3vw - 3px) 15.9vh,
      calc(13.4vw - 5px) 27.8vh,
      calc(15.4vw + 3px) 37.0vh,
      calc(4.1vw + 3px) 48.6vh,
      calc(29.7vw + 6px) 56.1vh,
      calc(73.8vw + 6px) 65.3vh,
      calc(78.1vw + 3px) 76.9vh,
      calc(75.5vw - 3px) 84.8vh,
      calc(9.5vw + 5px) 91.8vh;
  }
}

/* body::after: 10 bubbles, rises in 16s */
body::after {
  background-image:
    var(--bubble-2),
    var(--bubble-2),
    var(--bubble-2),
    var(--bubble-1),
    var(--bubble-1),
    var(--bubble-2),
    var(--bubble-3),
    var(--bubble-3),
    var(--bubble-3),
    var(--bubble-1);
  background-size: 49px, 49px, 53px, 50px, 23px, 59px, 33px, 47px, 59px, 27px;
  animation:
    hbc-rise 16s linear -12s infinite,
    hbc-sway-d 1.0s ease-in-out -12s infinite alternate;
}
@keyframes hbc-sway-d {
  from {
    background-position:
      calc(86.6vw - 3px) 3.8vh,
      calc(84.7vw + 3px) 14.5vh,
      calc(39.3vw - 3px) 28.6vh,
      calc(56.9vw + 3px) 34.7vh,
      calc(53.0vw - 3px) 42.0vh,
      calc(93.7vw + 3px) 52.6vh,
      calc(24.4vw - 6px) 65.7vh,
      calc(34.9vw - 8px) 74.7vh,
      calc(16.1vw - 3px) 85.1vh,
      calc(15.2vw + 3px) 96.0vh;
  }
  to {
    background-position:
      calc(86.6vw + 3px) 3.8vh,
      calc(84.7vw - 3px) 14.5vh,
      calc(39.3vw + 3px) 28.6vh,
      calc(56.9vw - 3px) 34.7vh,
      calc(53.0vw + 3px) 42.0vh,
      calc(93.7vw - 3px) 52.6vh,
      calc(24.4vw + 6px) 65.7vh,
      calc(34.9vw + 8px) 74.7vh,
      calc(16.1vw + 3px) 85.1vh,
      calc(15.2vw - 3px) 96.0vh;
  }
}

/* Respect the OS "reduce motion" setting */
@media (prefers-reduced-motion: reduce) {
  html::before, html::after, body::before, body::after {
    animation: none;
    display: none;
  }
}

/* ==========================================================
   Homebrew Channel look for T3 Code.
   Applied after the app's styles, together with hbc-bubbles.css.
   Uses only the stable selectors from T3 Code's theme guide.
   ========================================================== */

:root {
  /* Color variations override these two in build-theme.py. */
  --hbc-accent: #34beed;
  --hbc-bubble-filter: none;

  /* Light: the Homebrew Channel menu, soft white fading to grey-blue. */
  --hbc-backdrop: linear-gradient(180deg, #ffffff 0%, #f1f5f8 55%, #dde6ed 100%);
  --hbc-glass: rgba(255, 255, 255, 0.62);
  --hbc-glass-strong: rgba(255, 255, 255, 0.86);
  --hbc-tile-border: #c7d3dd;
  --hbc-tile-shadow: 0 2px 6px rgba(40, 70, 95, 0.12);
  --hbc-radius: 14px;
}

.dark {
  /* Dark: the Homebrew Channel underwater background. The image is
     fitted to the window width; its black foot blends into #000 below.
     --hbc-background-image is added by build-theme.py. */
  --hbc-backdrop: var(--hbc-background-image) center top / 100% auto no-repeat, #000;
  --hbc-glass: rgba(13, 24, 36, 0.6);
  --hbc-glass-strong: rgba(19, 34, 53, 0.88);
  --hbc-tile-border: #24405a;
  --hbc-tile-shadow: 0 2px 8px rgba(0, 0, 0, 0.35);
}

/* ---------- Backdrop: the gradient sits on the root, bubbles above it ---------- */

/* Tints the blue bubble art for color variations. */
html::before,
html::after,
body::before,
body::after {
  filter: var(--hbc-bubble-filter);
}

html {
  background: var(--hbc-backdrop) fixed !important;
  min-height: 100%;
}

body,
#root {
  background: transparent !important;
}

/* Clear every layer between the root and the chat so the bubbles show through. */
body *:has([data-workspace-area="conversation"]),
[data-workspace-area="conversation"],
.messages-timeline-scroll,
[data-chat-header] {
  background-color: transparent !important;
  background-image: none !important;
}

/* ---------- Sidebar: frosted panel ---------- */

[data-slot="sidebar"],
[data-slot="sidebar-inner"] {
  background: var(--hbc-glass) !important;
  backdrop-filter: blur(10px) saturate(1.1);
}

[data-thread-item] {
  border-radius: 10px !important;
}

/* ---------- Channel tiles: messages, composer, cards ---------- */

[data-user-message-bubble],
[data-slot="composer-host"],
.chat-markdown-codeblock {
  background: var(--hbc-glass-strong) !important;
  border: 2px solid var(--hbc-tile-border) !important;
  border-radius: var(--hbc-radius) !important;
  box-shadow: var(--hbc-tile-shadow) !important;
  backdrop-filter: blur(6px);
}

/* The chat box: a thin outline, as thick as the default theme's,
   that turns to the accent color while you type. */
[data-slot="composer-host"] {
  border-width: 1px !important;
}

[data-slot="composer-host"]:focus-within {
  border-color: var(--hbc-accent) !important;
}

/* Compact chip: a filled accent pill while it will compact before sending.
   aria-label is not on T3 Code's stable selector list, so check it after updates. */
[data-chat-composer-form] button[aria-label^="Compact "][aria-pressed="true"] {
  background: color-mix(in srgb, var(--hbc-accent) 22%, transparent) !important;
  box-shadow: inset 0 0 0 1px var(--hbc-accent) !important;
  border-radius: 999px !important;
  color: var(--hbc-accent) !important;
}

[data-chat-composer-form] button[aria-label^="Compact "][aria-pressed="true"] svg,
[data-chat-composer-form] button[aria-label^="Compact "][aria-pressed="true"] span {
  color: var(--hbc-accent) !important;
}

/* Popups keep T3 Code's own frosted glass and faint outline. The popup
   slots are often invisible wrappers, so a border on them draws a second
   frame around the real one. */

/* ---------- Buttons: rounded like the HBC bottom bar ---------- */

[data-slot="button"] {
  border-radius: 999px !important;
}

/* ---------- Scrollbars ---------- */

::-webkit-scrollbar-thumb,
[data-slot="scroll-area-thumb"] {
  background-color: var(--hbc-accent) !important;
  border-radius: 999px;
}

:root {
  --hbc-accent: #ff4d5a;
  --hbc-bubble-filter: hue-rotate(157deg);
}

.dark {
  --hbc-glass: rgba(36, 10, 12, 0.6);
  --hbc-glass-strong: rgba(50, 14, 18, 0.88);
  --hbc-tile-border: #5a2026;
}
